.sidebar { position:sticky; top:64px; height: calc(100vh - 64px); padding:1rem; border-right:1px solid var(--border); background: rgba(13,17,23,.54); transition: width .22s ease, padding .22s ease; overflow:auto; }
.sidebar-toggle { width:100%; justify-content:flex-start; margin-bottom:1rem; cursor:pointer; }
