.flow { display:grid; grid-template-columns: repeat(3, 1fr); gap:1rem; }
.badge { display:inline-flex; width:max-content; margin-top:1rem; padding:.35rem .7rem; border-radius:999px; color:#211602; background:var(--warning); font-weight:800; font-size:.82rem; }
.footer { border-top:1px solid var(--border); padding:3rem 0; background: rgba(0,0,0,.18); }
.footer-grid { display:grid; grid-template-columns: 1.3fr repeat(4, 1fr); gap:1.4rem; }
.footer a { display:block; color:var(--muted); margin:.45rem 0; font-size:.92rem; }
