from pathlib import Path
out=Path('/app/output')
required=['index.html','apps-build.html','storefronts.html','agents.html','support.html','styles.css','script.js','robots.txt','sitemap.xml']
missing=[f for f in required if not (out/f).exists()]
print('missing:', missing)
for html in out.glob('*.html'):
    text=html.read_text()
    for needle in ['stylesheet" href="styles.css','script src="script.js"']:
        if needle not in text: print('missing', needle, html.name)
    for href in ['index.html','apps-build.html','storefronts.html','agents.html','support.html']:
